import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import Motion from "@/components/Motion";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata = site.siteMeta.meta.Layout;

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }) {
  return (
    <html
      lang={site.siteMeta.lang}
      data-scroll-behavior="smooth"
      // Smooth scrolling, no sideways scroll, and the green scrollbar on the page and on every scroll box.
      // Every icon eases its hover moves with a small bounce.
      // Tailwind v4 leaves buttons on the default cursor, so everything clickable gets the pointer.
      className={`${fontVariables} max-w-full overflow-x-clip scroll-smooth [&::-webkit-scrollbar]:w-[9px] [&::-webkit-scrollbar-track]:bg-[#f1f5f3] [&::-webkit-scrollbar-thumb]:rounded-[4px] [&::-webkit-scrollbar-thumb]:bg-[#2a7c35] [&_*::-webkit-scrollbar]:w-[9px] [&_*::-webkit-scrollbar-track]:bg-[#f1f5f3] [&_*::-webkit-scrollbar-thumb]:rounded-[4px] [&_*::-webkit-scrollbar-thumb]:bg-[#2a7c35] [&_svg]:[transition:transform_0.3s_cubic-bezier(0.34,1.56,0.64,1),filter_0.3s_ease] [&_:where(a[href],button:not(:disabled),select,summary,[role=button])]:cursor-pointer`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="max-w-full overflow-x-clip bg-page font-sans text-navy antialiased">
        <Motion />
        {/*
          The whole site sits in one frame, at most 1920px wide and centred. Up to 1920px it fills the
          screen, so nothing changes; on wider screens or when the browser is zoomed out the page stays
          in the middle with equal space on both sides instead of stretching.
          Navbar and footer live here once, so every page gets them automatically.
        */}
        <div className="mx-auto flex min-h-screen w-full max-w-[1920px] flex-col overflow-x-clip bg-white">
          <Navbar />
          <ScrollToTop>{children}</ScrollToTop>
          <Footer />
        </div>
      </body>
    </html>
  );
}
